from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_nesting_level(group):
        stack = []
        max_nesting = 0
        current_nesting = 0

        for char in group:
            if char == '(':
                stack.append(char)
                current_nesting += 1
                max_nesting = max(max_nesting, current_nesting)
            elif char == ')':
                if stack and stack[-1] == '(':
                    stack.pop()
                    current_nesting -= 1
                else:
                    return -1

        if stack:
            return -1
        return max_nesting

    groups = paren_string.split()
    result = [calculate_nesting_level(group) for group in groups]

    return result

